/* The Public Suffix List: registrable domains and sites.
 *
 * The list is compiled into a front-coded table (psl_data.c, generated by
 * gen_psl.py; about 90 KB). au_psl_* look a host up against it with the
 * list's algorithm: the matching exception rule wins, else the matching
 * rule with the most labels, else "*" (the last label alone). */
#ifndef AURA_NET_PSL_H
#define AURA_NET_PSL_H

#include "../core/core.h"
#include "../url/url.h"

extern const char au_psl_date[];
extern const uint32_t au_psl_count, au_psl_block_size, au_psl_nblocks, au_psl_data_len;
extern const uint32_t au_psl_blocks[];
extern const uint8_t au_psl_data[];

/* The length in bytes of the public suffix at the end of host (a lower
 * case ASCII domain without a trailing dot), or 0 for an empty host. */
size_t au_psl_suffix_len(const char *host, size_t n);
/* Whether host is itself a public suffix ("co.uk", "github.io"). */
bool au_psl_is_public_suffix(const char *host);
/* The registrable domain (public suffix plus one label) of host, as a
 * pointer into host and a length; false when host is a public suffix or
 * an IP address. */
bool au_psl_registrable(const char *host, const char **dom, size_t *len);

/* Sites (HTML "site" with scheme): the scheme and registrable domain
 * (or the host when it has none, such as an IP address). URLs without a
 * tuple origin are opaque and same-site with nothing. */
void au_url_site(const AuUrl *u, AuBuf *out);
bool au_same_site(const AuUrl *a, const AuUrl *b);
/* Same registrable domain, ignoring the scheme (cookie "site for
 * cookies" before schemeful same-site). */
bool au_same_registrable(const char *host_a, const char *host_b);

#endif
